package ama.storage;
import ama.db.TransactionRunner;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceUtils;import java.sql.Connection;import javax.sql.DataSource;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
/** Real transaction/physical JDBC boundaries; this inert source cannot grant business authority. */
class Task11B3BudgetFaultTest {
 static final String SCOPE="selected-scope",ACTOR="selected-owner",MEETING="selected-meeting",PUB="00000000-0000-4000-8000-000000000002",OP="selected-operation",TASK="00000000-0000-4000-8000-000000000001";
 static final String RECEIPT="INSERT INTO idempotency_record(scope_hash,actor_id,resource_id,operation,key_hash,request_hash,state,http_status,created_at) VALUES (?,?,?,?,?,?,'SUCCEEDED',0,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE scope_hash=idempotency_record.scope_hash";
 static final String SUB="INSERT INTO publication_submission(task_id,publication_id,submission_no,created_at) VALUES (?,?,?,UTC_TIMESTAMP(6))";
 void receipt(JdbcTemplate j,String scope){j.update(RECEIPT,scope,ACTOR,MEETING,"PUBLICATION_RESUBMIT","key-hash","request-hash");}
 @Test void actualFinalWriteIsReachedButNotDelegatedAndEarlierProductWritesPhysicallyRollback(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();DataSource source=fault.wrap(fake);fault.arm(SCOPE,ACTOR,MEETING,PUB,OP);assertThrows(Task11B3BudgetFault.FinalGateReached.class,()->new TransactionRunner(source).required(()->{var j=new JdbcTemplate(source);receipt(j,SCOPE);j.update("INSERT INTO durable_task(id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id) VALUES (?,?,?,?,?,?,?,?)",TASK,"KNOWLEDGE_PUBLISH_V1","KNOWLEDGE_PUBLISH","MEETING",MEETING,"producer","PUBLICATION",PUB);ama.task.Task11B3BudgetEngineProbe.replace(source,TASK,MEETING,PUB,OP);j.update(SUB,TASK,PUB,8);return null;}));assertTrue(fault.rollbackOnlyBeforeFirstWrite&&fault.physicalRollbackReturned&&fault.finalReached);assertEquals(4,fault.delegatedWrites);assertTrue(fake.sql.contains(RECEIPT));assertFalse(fake.sql.contains(SUB));assertEquals(0,fake.commits);assertEquals(1,fake.rollbacks);}
 @Test void realEngineForeignOperationOrSubjectIsRejectedBeforeThePhysicalCas(){for(boolean wrongSubject:new boolean[]{true,false}){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();var source=fault.wrap(fake);fault.arm(SCOPE,ACTOR,MEETING,PUB,OP);assertThrows(AssertionError.class,()->new TransactionRunner(source).required(()->{var j=new JdbcTemplate(source);receipt(j,SCOPE);j.update("INSERT INTO durable_task(id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id) VALUES (?,?,?,?,?,?,?,?)",TASK,"KNOWLEDGE_PUBLISH_V1","KNOWLEDGE_PUBLISH","MEETING",MEETING,"producer","PUBLICATION",PUB);ama.task.Task11B3BudgetEngineProbe.replace(source,TASK,wrongSubject?"foreign-meeting":MEETING,PUB,wrongSubject?OP:"foreign-operation");return null;}));assertEquals(2,fault.delegatedWrites);assertTrue(fake.sql.stream().noneMatch(sql->sql.startsWith("UPDATE external_operation")));assertTrue(fault.physicalRollbackReturned);assertFalse(fault.finalReached);assertEquals(0,fake.commits);}}
 @Test void selectedFirstCommandCannotCommitWhenCallbackReturnsNormally(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();DataSource source=fault.wrap(fake);fault.arm(SCOPE,ACTOR,MEETING,PUB,OP);assertThrows(RuntimeException.class,()->new TransactionRunner(source).required(()->{receipt(new JdbcTemplate(source),SCOPE);return null;}));assertTrue(fault.rollbackOnlyBeforeFirstWrite&&fault.physicalRollbackReturned);assertFalse(fault.finalReached);assertEquals(0,fake.commits);assertEquals(1,fake.rollbacks);}
 @Test void forcedConnectionCommitStillDelegatesOnlyRollback(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();DataSource source=fault.wrap(fake);fault.arm(SCOPE,ACTOR,MEETING,PUB,OP);assertThrows(RuntimeException.class,()->new TransactionRunner(source).required(()->{receipt(new JdbcTemplate(source),SCOPE);var connection=DataSourceUtils.getConnection(source);try{connection.commit();}finally{DataSourceUtils.releaseConnection(connection,source);}return null;}));assertTrue(fault.physicalRollbackReturned);assertEquals(0,fake.commits);assertTrue(fake.rollbacks>=1);}
 @Test void foreignScopeAndUnselectedBusinessWritesFailBeforeDelegation(){for(boolean receipt:new boolean[]{true,false}){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();DataSource source=fault.wrap(fake);fault.arm(SCOPE,ACTOR,MEETING,PUB,OP);var error=assertThrows(AssertionError.class,()->new TransactionRunner(source).required(()->{var j=new JdbcTemplate(source);if(receipt)receipt(j,"foreign-scope");else j.update("UPDATE durable_task SET state='FAILED' WHERE id=?","foreign-task");return null;}));assertEquals("Unselected diagnostic business write",error.getMessage());assertEquals(0,fault.delegatedWrites);assertTrue(fake.sql.stream().noneMatch(sql->sql.startsWith("INSERT ")||sql.startsWith("UPDATE ")));assertEquals(0,fake.commits);}}
 @Test void foreignPublicationAndMarkerCannotReachPhysicalStatement(){for(String sql:new String[]{SUB,"UPDATE external_execution SET state='MARKED',task_attempt=?,marked_at=? WHERE id=?"}){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();DataSource source=fault.wrap(fake);fault.arm(SCOPE,ACTOR,MEETING,PUB,OP);assertThrows(AssertionError.class,()->new TransactionRunner(source).required(()->{var j=new JdbcTemplate(source);receipt(j,SCOPE);if(sql.equals(SUB))j.update(sql,"new-task","foreign-publication",8);else j.update(sql,1,"time","execution");return null;}));assertFalse(fake.sql.contains(sql));assertEquals(0,fake.commits);assertTrue(fault.physicalRollbackReturned);}}
 @Test void physicalRollbackFailureIsNeverCredited(){var fake=new Task11B3LocalFaultTest.Fake();fake.rollbackThrows=true;var fault=new Task11B3BudgetFault();DataSource source=fault.wrap(fake);fault.arm(SCOPE,ACTOR,MEETING,PUB,OP);assertThrows(RuntimeException.class,()->new TransactionRunner(source).required(()->{receipt(new JdbcTemplate(source),SCOPE);throw new IllegalStateException("Owned diagnostic failure");}));assertFalse(fault.physicalRollbackReturned);assertEquals(0,fake.commits);}
 @Test void exactTransactionInitializationAndStableConnectionRemainUsableWithoutDiagnosticWrite(){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();DataSource source=fault.wrap(fake);assertEquals("read-only",new TransactionRunner(source).required(()->{Connection connection=DataSourceUtils.getConnection(source);assertSame(connection,connection.unwrap(Connection.class));try(var statement=connection.prepareStatement("SELECT 1")){assertSame(connection,statement.getConnection());}DataSourceUtils.releaseConnection(connection,source);return "read-only";}));assertEquals(1,fake.commits);assertFalse(fault.physicalRollbackReturned);}
 @Test void unrelatedSetAndLiteralBatchAreRejectedByTheActualGuard(){for(String sql:new String[]{"SET sql_mode='ANSI'","SELECT 1; DELETE FROM durable_task"}){var fake=new Task11B3LocalFaultTest.Fake();var fault=new Task11B3BudgetFault();var source=fault.wrap(fake);var failure=assertThrows(AssertionError.class,()->new TransactionRunner(source).required(()->{new JdbcTemplate(source).execute(sql);return null;}));assertEquals(sql.startsWith("SELECT")?"Diagnostic multi-statement SQL forbidden":"Unreleased diagnostic SQL",failure.getMessage());assertFalse(fake.sql.contains(sql));assertEquals(0,fake.commits);}}
}